    #[test]
    fn finishframe_uses_jitdriver_result_type_when_available() {
        // pyjitpl.py:2493 — `result_type = self.jitdriver_sd.result_type`.
        // The DoneWithThisFrame variant is determined by the active
        // jitdriver's declared return type, not by the resultbox kind.
        // Here the popped frame has jitdriver_sd=Some(0) and that
        // driver declares result_type=Ref, so a tuple with kind=Int but
        // value 0xfeed is reported as DoneWithThisFrameRef(0xfeed).
        use crate::jitcode::{JitArgKind, JitCodeBuilder};
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(0, 0);
        let jitcode = builder.finish();
        jitcode.set_jitdriver_sd(0);
        let mut meta = MetaInterp::<()>::new(0);
        meta.finish_setup_descrs_for_jitdrivers();
        let driver = crate::jitdriver::JitDriverStaticData {
            index: None,
            name: "jitdriver".into(),
            vars: vec![],
            virtualizable: None,
            flat_entry: None,
            result_type: majit_ir::Type::Ref,
            is_recursive: false,
            mainjitcode: None,
            mainjitcode_loader: None,
            mainjitcode_loaded: std::sync::OnceLock::new(),
            portal_runner_adr: 0,
            handle_jitexc_from_bh: None,
            virtualizable_info: None,
            greenfield_info: None,
            index_of_virtualizable: -1,
            portal_calldescr: None,
            portal_finishtoken: None,
            propagate_exc_descr: None,
            red_args_types: vec![],
            no_loop_header: false,
            assembler_helper_adr: 0,
            vable_token_descr: None,
            frame_value_count_fn: None,
            get_unique_id: None,
            warmstate: None,
        };
        {
            let MetaInterp {
                staticdata,
                backend,
                ..
            } = &mut meta;
            let sd = std::sync::Arc::get_mut(staticdata).unwrap();
            let _ = sd.register_jitdriver_sd(driver, backend);
        }
        meta.framestack.push(crate::pyjitpl::MIFrame::new(
            std::sync::Arc::new(jitcode),
            0,
        ));
        let result = meta.finishframe(Some((JitArgKind::Int, 0, OpRef::int_op(1), 0xfeed)), true);
        assert!(matches!(
            result,
            Err(FinishFrameSignal::Done(DoneWithThisFrame::Ref(r))) if r.0 == 0xfeed
        ));
    }

    #[test]
    fn perform_call_pushes_frame_and_setup_call_writes_argboxes() {
        // pyjitpl.py perform_call → newframe → setup_call →
        // raise ChangeFrame.  After the call, framestack should have one
        // frame whose typed register banks reflect the argboxes.
        use crate::jitcode::{JitArgKind, JitCodeBuilder};
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(0, 0);
        builder.load_const_i_value(1, 0);
        builder.load_const_r_value(0, 0);
        builder.load_const_f_value(0, 0);
        let jitcode = std::sync::Arc::new(builder.finish());
        let mut meta = MetaInterp::<()>::new(0);
        meta.finish_setup_descrs_for_jitdrivers();
        let result = meta.perform_call(
            jitcode,
            &[
                (JitArgKind::Int, OpRef::int_op(10), 100),
                (JitArgKind::Ref, OpRef::ref_op(20), 200),
                (JitArgKind::Int, OpRef::int_op(11), 101),
                (JitArgKind::Float, OpRef::float_op(30), 300),
            ],
            None,
        );
        assert!(matches!(result, Err(ChangeFrame)));
        assert_eq!(meta.framestack.len(), 1);
        let f = meta.framestack.current_mut();
        assert_eq!(f.pc, 0);
        assert_eq!(f.int_regs[0], Some(OpRef::int_op(10)));
        assert_eq!(f.int_regs[1], Some(OpRef::int_op(11)));
        assert_eq!(f.ref_regs[0], Some(OpRef::ref_op(20)));
        assert_eq!(f.float_regs[0], Some(OpRef::float_op(30)));
    }

    #[test]
    fn finishframe_writes_result_into_caller_then_change_frame() {
        // pyjitpl.py — popframe + framestack[-1].make_result_of_lastop +
        // raise ChangeFrame.
        //
        // RPython parity (pyjitpl.py, 2479-2486): when
        // `make_result_of_lastop` fires on the caller frame after the
        // callee returns, it reads `_resulttypes[self.pc]` and asserts
        // the recorded kind matches the runtime kind.  To exercise that
        // assertion (which `MIFrame::make_result_of_lastop` mirrors as
        // a `debug_assert`), the caller jitcode must contain a real
        // typed-call bytecode whose end-of-instruction position is
        // reflected in `caller.pc` at finishframe time.
        use crate::jitcode::{JitArgKind, JitCodeBuilder};
        let mut builder_caller = JitCodeBuilder::new();
        builder_caller.load_const_i_value(0, 0);
        builder_caller.load_const_i_value(1, 0);
        // assembler.py:217-219 — `inline_call_irf_i` records
        // `resulttypes[end_pc] = 'i'` so the post-call pc lookup
        // succeeds at make_result_of_lastop.  The sub_jitcode index
        // (0) is a placeholder — perform_call(callee) below pushes
        // the actual callee onto the framestack regardless of the
        // bytecode operand, since this test never runs the dispatch
        // loop.
        builder_caller.inline_call_irf_i(0, &[], &[], &[], Some(1));
        let post_call_pc = builder_caller.current_pos();
        let caller = std::sync::Arc::new(builder_caller.finish());
        let builder_callee = JitCodeBuilder::new();
        let callee = std::sync::Arc::new(builder_callee.finish());

        let mut meta = MetaInterp::<()>::new(0);
        meta.finish_setup_descrs_for_jitdrivers();
        // Push caller, then advance caller.pc to the post-call
        // position the way the bytecode dispatch loop would (the
        // opimpl reads operand bytes and bumps `pc` past the entire
        // `inline_call_irf_i` instruction before raising ChangeFrame
        // and yielding control to the callee — pyjitpl.py).
        meta.perform_call(caller, &[], None).unwrap_err();
        meta.framestack.current_mut().pc = post_call_pc;
        meta.perform_call(callee, &[], None).unwrap_err();
        assert_eq!(meta.framestack.len(), 2);

        // Return from callee: write result into caller register 1.
        // `make_result_of_lastop` (frame.rs) checks
        // `caller.jitcode.body.resulttypes[caller.pc]` matches the
        // runtime kind — both are 'i' here, so the debug_assert
        // passes and the result is written.
        let result = meta.finishframe(Some((JitArgKind::Int, 1, OpRef::int_op(42), 4242)), true);
        assert!(matches!(result, Err(FinishFrameSignal::ChangeFrame)));
        assert_eq!(meta.framestack.len(), 1);
        let caller_frame = meta.framestack.current_mut();
        assert_eq!(caller_frame.pc, post_call_pc);
        assert_eq!(caller_frame.int_regs[1], Some(OpRef::int_op(42)));
    }

    #[test]
    fn finishframe_void_return_skips_make_result_of_lastop() {
        use crate::jitcode::JitCodeBuilder;
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(0, 0);
        let caller = std::sync::Arc::new(builder.finish());
        let callee = std::sync::Arc::new(JitCodeBuilder::new().finish());

        let mut meta = MetaInterp::<()>::new(0);
        meta.finish_setup_descrs_for_jitdrivers();
        meta.perform_call(caller, &[], None).unwrap_err();
        // Mutate the caller's register 0 so we can detect any
        // accidental write triggered by the void return.
        meta.framestack.current_mut().int_regs[0] = Some(OpRef::int_op(7));
        meta.perform_call(callee, &[], None).unwrap_err();
        let result = meta.finishframe(None, true);
        assert!(matches!(result, Err(FinishFrameSignal::ChangeFrame)));
        // Void return preserves whatever was already there in the caller.
        assert_eq!(
            meta.framestack.current_mut().int_regs[0],
            Some(OpRef::int_op(7))
        );
    }

    #[test]
    fn portal_trace_abort_finishes_each_live_frame_without_replaying() {
        use crate::jitcode::{JitArgKind, JitCodeBuilder};
        use crate::jitexc::JitException;

        // The first addition executes while tracing. Cancellation must finish
        // the second addition and return through the caller's own register
        // bank: 40 + 1 + 1 + 100 = 142. Restarting the callee repeats an effect;
        // dropping it loses its return and the caller's continuation.
        let mut callee = JitCodeBuilder::new();
        callee.record_binop_i(0, OpCode::IntAdd, 0, 1);
        callee.record_binop_i(0, OpCode::IntAdd, 0, 1);
        callee.int_return(0);
        let mut portal = JitCodeBuilder::new();
        let callee = callee.finish();
        callee.set_index(1);
        let callee_index = portal.add_sub_jitcode(callee);
        portal.inline_call_ir_i(callee_index, &[(1, 0), (2, 1)], &[], Some(3));
        portal.record_binop_i(3, OpCode::IntAdd, 3, 0);
        portal.int_return(3);
        let portal = portal.finish();
        portal.set_index(0);
        portal.set_jitdriver_sd(0);

        let mut meta = MetaInterp::<()>::new(0);
        meta.finish_setup_descrs_for_jitdrivers();
        meta.force_start_tracing(
            0,
            (0, 0),
            None,
            &[Value::Int(100), Value::Int(40), Value::Int(1)],
        );
        meta.initialize_state_from_start(
            Arc::new(portal),
            &[
                (JitArgKind::Int, OpRef::input_arg_int(0), 100),
                (JitArgKind::Int, OpRef::input_arg_int(1), 40),
                (JitArgKind::Int, OpRef::input_arg_int(2), 1),
            ],
        );
        meta.trace_ctx().unwrap().set_trace_limit(0);
        struct Sym;
        impl crate::JitCodeSym for Sym {
            fn total_slots(&self) -> usize {
                0
            }
            fn loop_header_pc(&self) -> usize {
                0
            }
        }
        assert!(matches!(
            meta.interpret(&mut Sym, 0),
            crate::TraceAction::Abort
        ));
        assert_eq!(meta.framestack.len(), 2);
        let i0 = meta.framestack.frames.last().unwrap().int_regs[0].unwrap();
        assert_eq!(meta.tracing.as_ref().unwrap().box_bits(i0), Some(41));
        let mut builder = crate::blackhole::build_inline_call_only_bh_builder(&[(
            "recursive_call_v/iIRFIRF",
            34,
        )]);
        assert_eq!(
            meta.run_blackhole_interp_to_cancel_tracing(
                SwitchToBlackhole::bad_loop(),
                &mut builder,
                None,
                None,
                None,
            ),
            JitException::DoneWithThisFrameInt(142),
        );
        assert!(meta.framestack.is_empty());
        assert!(!meta.is_tracing());
        assert_eq!(meta.stats.loops_aborted, 1);
    }

    #[test]
    fn portal_trace_abort_preserves_pending_exception() {
        use crate::jitcode::{JitArgKind, JitCodeBuilder};
        use crate::jitexc::JitException;
        // blackhole.py convert_and_run_from_pyjitpl distinguishes a caught
        // last exception from one that SwitchToBlackhole is still raising.
        for raising_exception in [false, true] {
            let mut portal = JitCodeBuilder::new();
            portal.record_binop_i(0, OpCode::IntAdd, 0, 1);
            portal.last_exc_value(0);
            portal.ref_return(0);
            let portal = portal.finish();
            portal.set_index(0);
            portal.set_jitdriver_sd(0);
            let mut meta = MetaInterp::<()>::new(0);
            // `jitdrivers_sd[0]` for the portal jitcode stamped above.
            meta.ensure_default_driver_sd();
            meta.finish_setup_descrs_for_jitdrivers();
            meta.force_start_tracing(0, (0, 0), None, &[Value::Int(40), Value::Int(2)]);
            meta.initialize_state_from_start(
                Arc::new(portal),
                &[
                    (JitArgKind::Int, OpRef::input_arg_int(0), 40),
                    (JitArgKind::Int, OpRef::input_arg_int(1), 2),
                ],
            );
            meta.last_exc_value = 0xfeed;
            meta.last_exc_box = Some(OpRef::const_ptr(majit_ir::GcRef(0xfeed)));
            meta.trace_ctx().unwrap().set_trace_limit(0);
            struct Sym;
            impl crate::JitCodeSym for Sym {
                fn total_slots(&self) -> usize {
                    0
                }
                fn loop_header_pc(&self) -> usize {
                    0
                }
            }
            assert!(matches!(
                meta.interpret(&mut Sym, 0),
                crate::TraceAction::Abort
            ));
            let mut builder = crate::blackhole::build_inline_call_only_bh_builder(&[(
                "recursive_call_v/iIRFIRF",
                34,
            )]);
            let outcome = meta.run_blackhole_interp_to_cancel_tracing(
                SwitchToBlackhole {
                    reason: counters::ABORT_ESCAPE,
                    raising_exception,
                },
                &mut builder,
                None,
                None,
                None,
            );
            let exception = majit_ir::GcRef(0xfeed);
            assert_eq!(
                outcome,
                if raising_exception {
                    JitException::ExitFrameWithExceptionRef(exception)
                } else {
                    JitException::DoneWithThisFrameRef(exception)
                }
            );
        }
    }

    #[test]
    fn cancel_tracing_blackhole_publishes_each_frame_vable() {
        use crate::jitcode::{JitArgKind, JitCodeBuilder};
        use std::cell::RefCell;

        let mut callee = JitCodeBuilder::new();
        callee.record_binop_i(0, OpCode::IntAdd, 0, 1);
        callee.record_binop_i(0, OpCode::IntAdd, 0, 1);
        callee.int_return(0);
        let mut portal = JitCodeBuilder::new();
        let callee = callee.finish();
        callee.set_index(1);
        let callee_index = portal.add_sub_jitcode(callee);
        portal.inline_call_ir_i(callee_index, &[(1, 0), (2, 1)], &[], Some(3));
        portal.record_binop_i(3, OpCode::IntAdd, 3, 0);
        portal.int_return(3);
        let portal = portal.finish();
        portal.set_index(0);
        portal.set_jitdriver_sd(0);

        let mut meta = MetaInterp::<()>::new(0);
        meta.finish_setup_descrs_for_jitdrivers();
        meta.force_start_tracing(
            0,
            (0, 0),
            None,
            &[Value::Int(100), Value::Int(40), Value::Int(1)],
        );
        meta.initialize_state_from_start(
            Arc::new(portal),
            &[
                (JitArgKind::Int, OpRef::input_arg_int(0), 100),
                (JitArgKind::Int, OpRef::input_arg_int(1), 40),
                (JitArgKind::Int, OpRef::input_arg_int(2), 1),
            ],
        );
        meta.trace_ctx().unwrap().set_trace_limit(0);
        struct Sym;
        impl crate::JitCodeSym for Sym {
            fn total_slots(&self) -> usize {
                0
            }
            fn loop_header_pc(&self) -> usize {
                0
            }
        }
        assert!(matches!(
            meta.interpret(&mut Sym, 0),
            crate::TraceAction::Abort
        ));
        assert_eq!(meta.framestack.len(), 2);

        let entered = RefCell::new(Vec::new());
        let left = RefCell::new(Vec::new());
        let on_enter = |frame_ptr: i64| entered.borrow_mut().push(frame_ptr);
        let on_leave = |frame_ptr: i64| left.borrow_mut().push(frame_ptr);
        let per_frame = [(0x1000, 0), (0x2000, 0)];
        let mut builder = crate::blackhole::build_inline_call_only_bh_builder(&[(
            "recursive_call_v/iIRFIRF",
            34,
        )]);
        let _ = meta.run_blackhole_interp_to_cancel_tracing(
            SwitchToBlackhole::bad_loop(),
            &mut builder,
            Some(&per_frame),
            Some(&on_enter),
            Some(&on_leave),
        );
        // Innermost first: the callee must be published as its own vable.
        // Sharing the portal frame would enter/leave 0x1000 for that level.
        assert_eq!(entered.borrow()[0], 0x2000);
        assert!(left.borrow().contains(&0x2000));
    }

    #[test]
    fn initialize_state_from_start_clears_and_seeds_framestack() {
        // pyjitpl.py:3266-3275 — start a fresh portal: framestack reset,
        // mainjitcode pushed, original_boxes copied via setup_call.
        use crate::jitcode::{JitArgKind, JitCodeBuilder};
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(0, 0);
        let mainjitcode = builder.finish();
        // pyjitpl.py:3268-3272 — the mainjitcode is the portal jitcode
        // and must carry jitdriver_sd so portal_call_depth bumps from
        // -1 to 0 inside newframe (matching the upstream assert).
        mainjitcode.set_jitdriver_sd(0);
        let mainjitcode = std::sync::Arc::new(mainjitcode);

        let mut meta = MetaInterp::<()>::new(0);
        meta.finish_setup_descrs_for_jitdrivers();
        // Pre-populate framestack with a stale frame to verify reset.
        meta.perform_call(mainjitcode.clone(), &[], None)
            .unwrap_err();
        assert_eq!(meta.framestack.len(), 1);
        // `pyjitpl.py self.virtualref_boxes = []` is structurally
        // enforced now: the backing vector lives on `TraceCtx`, which
        // is rebuilt per `MetaInterp::setup_tracing` cycle, so no
        // pre-populate / re-assert is needed here.

        meta.initialize_state_from_start(mainjitcode, &[(JitArgKind::Int, OpRef::int_op(7), 7)]);
        assert_eq!(meta.framestack.len(), 1);
        assert_eq!(
            meta.framestack.current_mut().int_regs[0],
            Some(OpRef::int_op(7))
        );
        // pyjitpl.py initialize_original_boxes assert.
        assert_eq!(meta.portal_call_depth, 0);
    }

    #[test]
    fn seed_root_portal_frame_setup_call_writes_original_boxes() {
        // pyjitpl.py initialize_state_from_start: setup_call packs
        // greens then reds into the typed banks.
        use crate::jitcode::{JitArgKind, JitCodeBuilder};
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(0, 0);
        builder.load_const_i_value(1, 0);
        builder.load_const_r_value(0, 0);
        builder.load_const_r_value(1, 0);
        builder.load_const_r_value(2, 0);
        let mainjitcode = builder.finish();
        mainjitcode.set_jitdriver_sd(0);
        let mainjitcode = std::sync::Arc::new(mainjitcode);

        let mut meta = MetaInterp::<()>::new(0);
        meta.finish_setup_descrs_for_jitdrivers();
        meta.seed_root_portal_frame(
            mainjitcode,
            &[
                (JitArgKind::Int, OpRef::const_int(11), 11),
                (JitArgKind::Int, OpRef::const_int(0), 0),
                (
                    JitArgKind::Ref,
                    OpRef::const_ptr(majit_ir::GcRef(0xabc)),
                    0xabc,
                ),
                (
                    JitArgKind::Ref,
                    OpRef::input_arg_typed(0, majit_ir::Type::Ref),
                    0x100,
                ),
                (
                    JitArgKind::Ref,
                    OpRef::input_arg_typed(1, majit_ir::Type::Ref),
                    0x200,
                ),
            ],
        );
        let frame = meta.framestack.current_mut();
        assert_eq!(frame.pc, 0);
        assert_eq!(frame.int_value_for_blackhole(0), Some(11));
        assert_eq!(frame.int_value_for_blackhole(1), Some(0));
        assert_eq!(frame.ref_value_for_blackhole(0), Some(0xabc));
        assert_eq!(
            frame.ref_regs[1],
            Some(OpRef::input_arg_typed(0, majit_ir::Type::Ref))
        );
        assert_eq!(
            frame.ref_regs[2],
            Some(OpRef::input_arg_typed(1, majit_ir::Type::Ref))
        );
        assert_eq!(meta.portal_call_depth, 0);
        assert_eq!(meta.call_ids, vec![0]);
    }

    #[test]
    fn begin_attempt_resets_constructor_fields_and_keeps_warmstate() {
        // warmstate.py bound_reached / compile.py
        // _trace_and_compile_from_bridge: each attempt is a new
        // MetaInterp. The long-lived object keeps warm_state.
        use crate::jitcode::JitCodeBuilder;
        let mut meta = MetaInterp::<()>::new(10);
        meta.finish_setup_descrs_for_jitdrivers();
        meta.cancel_count = 3;
        meta.portal_call_depth = 4;
        meta.current_call_id = 9;
        meta.call_ids = vec![1, 2];
        meta.last_exc_value = 0xabc;
        meta.forced_virtualizable = 0xdef;
        meta.ovf_flag = true;
        meta.trace_length_at_last_tco = 12;
        let leftover = std::sync::Arc::new(JitCodeBuilder::new().finish());
        meta.perform_call(leftover, &[], None).unwrap_err();
        assert!(!meta.framestack.is_empty());

        meta.begin_attempt();

        assert_eq!(meta.cancel_count, 0);
        assert_eq!(meta.portal_call_depth, 0);
        assert_eq!(meta.current_call_id, 0);
        assert!(meta.call_ids.is_empty());
        assert_eq!(meta.last_exc_value, 0);
        assert_eq!(meta.forced_virtualizable, 0);
        assert!(!meta.ovf_flag);
        assert_eq!(meta.trace_length_at_last_tco, -1);
        assert!(meta.framestack.is_empty());
        assert!(
            meta.portal_trace_positions
                .as_ref()
                .is_some_and(|p| p.is_empty())
        );
        // Long-lived owner: the same WarmEnterState instance remains.
        assert_eq!(meta.warm_state_for_driver(0).threshold(), 10);
    }

    #[test]
    fn interpret_walks_the_seeded_root_portal_frame() {
        // pyjitpl.py `_compile_and_run_once`: initialize_state_from_start
        // then interpret() on that framestack, no extra push/pop.
        use crate::BackEdgeAction;
        use crate::jitcode::JitCodeBuilder;
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(0, 0);
        let jitcode = std::sync::Arc::new(builder.finish());
        jitcode.set_jitdriver_sd(0);

        let mut meta = MetaInterp::<()>::new(0);
        meta.finish_setup_descrs_for_jitdrivers();
        let action = meta.force_start_tracing(0, (0, 0), None, &[]);
        assert!(matches!(action, BackEdgeAction::StartedTracing));
        meta.seed_root_portal_frame(
            jitcode,
            &[(crate::jitcode::JitArgKind::Int, OpRef::const_int(0), 0)],
        );
        assert_eq!(meta.framestack.len(), 1);

        struct NoopSym;
        impl crate::JitCodeSym for NoopSym {
            fn total_slots(&self) -> usize {
                0
            }
            fn loop_header_pc(&self) -> usize {
                0
            }
        }
        let mut sym = NoopSym;
        let action = meta.interpret(&mut sym, 0);
        assert!(matches!(
            action,
            crate::TraceAction::Continue
                | crate::TraceAction::Abort
                | crate::TraceAction::Finish { .. }
        ));
    }

