    #[test]
    fn test_front_target_inputarg_types_uses_saved_front_label_contract() {
        let mut meta = MetaInterp::<()>::new(1);
        meta.finish_setup_descrs_for_jitdrivers();
        let green_key = 7;
        let trace_id = 11;
        let token = std::sync::Arc::new(JitCellToken::new(3));
        let start_token = crate::history::TargetToken::new_preamble(0);
        let start_descr = start_token.as_jump_target_descr();
        let inputargs = [InputArg::new_ref_rc(0), InputArg::new_ref_rc(1)];
        let ops = vec![
            mk_op(OpCode::SameAsR, &[OpRef::input_arg_ref(0)], 2),
            mk_op(OpCode::IntAdd, &[OpRef::int_op(100), OpRef::int_op(101)], 3),
            mk_op_with_descr(
                OpCode::Label,
                &[
                    OpRef::input_arg_ref(0),
                    OpRef::input_arg_ref(1),
                    OpRef::ref_op(2),
                    OpRef::int_op(3),
                ],
                OpRef::NONE.raw(),
                start_descr,
            ),
        ];
        let mut constants: majit_ir::ConstMap<majit_ir::Const> = majit_ir::ConstMap::default();
        constants.insert(100, majit_ir::Const::Int(1));
        constants.insert(101, majit_ir::Const::Int(2));
        let mut traces = crate::FxIndexMap::default();
        traces.insert(
            trace_id,
            CompiledTrace {
                inputargs: inputargs.to_vec(),
                ops: ops.into_iter().map(OpRc::new).collect(),
                constants,
                exit_layouts: crate::FxIndexMap::default(),
                terminal_exit_layouts: crate::FxIndexMap::default(),
            },
        );
        // `compile.py` — `send_loop_to_backend` registers the token
        // with `MemoryManager` BEFORE any cell sees it. The cell keeps only a
        // weak handle (`warmstate.py:188`), so `alive_loops` is what keeps
        // `token` alive past this fixture's own local.
        meta.warm_state_for_driver(0)
            .memory_manager
            .keep_loop_alive(&token);
        meta.warm_state_for_driver(0)
            .attach_procedure_to_interp(green_key, std::sync::Arc::clone(&token));
        meta.insert_compiled_loop(
            green_key,
            CompiledEntry {
                token: std::sync::Arc::downgrade(&token),
                meta: std::sync::Arc::new(()),
                front_target_tokens: vec![start_token],
                front_entry_index: Some(0),
                front_target_source_positions: None,
                root_trace_id: trace_id,
                traces,
                previous_tokens: Vec::new(),
                loop_header_pc: None,
                next_global_opref: 0,
            },
        );

        assert_eq!(
            meta.front_target_inputarg_types(green_key),
            Some(vec![Type::Ref, Type::Ref, Type::Ref, Type::Int])
        );
    }

    /// A `MetaInterp` holding one compiled loop whose front target LABEL takes
    /// `(Int, Ref, Ref, Ref)`, with `source_positions` as given.
    fn meta_with_front_label_int_ref_ref_ref(
        green_key: u64,
        source_positions: Option<Vec<usize>>,
    ) -> (MetaInterp<()>, std::sync::Arc<JitCellToken>) {
        let mut meta = MetaInterp::<()>::new(1);
        meta.finish_setup_descrs_for_jitdrivers();
        let trace_id = 11;
        let token = std::sync::Arc::new(JitCellToken::new(3));
        let start_token = crate::history::TargetToken::new_preamble(0);
        let start_descr = start_token.as_jump_target_descr();
        let inputargs = [InputArg::new_ref_rc(0), InputArg::new_ref_rc(1)];
        let ops = vec![
            mk_op(OpCode::SameAsR, &[OpRef::input_arg_ref(0)], 2),
            mk_op(OpCode::IntAdd, &[OpRef::int_op(100), OpRef::int_op(101)], 3),
            mk_op_with_descr(
                OpCode::Label,
                &[
                    OpRef::int_op(3),
                    OpRef::input_arg_ref(0),
                    OpRef::input_arg_ref(1),
                    OpRef::ref_op(2),
                ],
                OpRef::NONE.raw(),
                start_descr,
            ),
        ];
        let mut constants: majit_ir::ConstMap<majit_ir::Const> = majit_ir::ConstMap::default();
        constants.insert(100, majit_ir::Const::Int(1));
        constants.insert(101, majit_ir::Const::Int(2));
        let mut traces = crate::FxIndexMap::default();
        traces.insert(
            trace_id,
            CompiledTrace {
                inputargs: inputargs.to_vec(),
                ops: ops.into_iter().map(OpRc::new).collect(),
                constants,
                exit_layouts: crate::FxIndexMap::default(),
                terminal_exit_layouts: crate::FxIndexMap::default(),
            },
        );
        // `compile.py` — `send_loop_to_backend` registers the token
        // with `MemoryManager` BEFORE any cell sees it. The cell keeps only a
        // weak handle (`warmstate.py:188`), so `alive_loops` is what keeps
        // `token` alive past this fixture's own local.
        meta.warm_state_for_driver(0)
            .memory_manager
            .keep_loop_alive(&token);
        meta.warm_state_for_driver(0)
            .attach_procedure_to_interp(green_key, std::sync::Arc::clone(&token));
        meta.insert_compiled_loop(
            green_key,
            CompiledEntry {
                token: std::sync::Arc::downgrade(&token),
                meta: std::sync::Arc::new(()),
                front_target_tokens: vec![start_token],
                front_entry_index: Some(0),
                front_target_source_positions: source_positions,
                root_trace_id: trace_id,
                traces,
                previous_tokens: Vec::new(),
                loop_header_pc: None,
                next_global_opref: 0,
            },
        );
        (meta, token)
    }

    /// The LABEL's argument order is its own, not the frontend's state-field
    /// order, and the two can agree in length while disagreeing in position.
    /// A downstream interpreter under the cranelift backend hit exactly that:
    /// four state values `(Int, Int, Ref, Ref)` entered a four-argument
    /// `(Int, Ref, Ref, Ref)` LABEL, and compiled code dereferenced the second
    /// `Int` as a pointer.
    #[test]
    fn test_pack_front_target_live_values_reorders_and_refuses_mismatches() {
        let state_order = vec![
            Value::Int(23),
            Value::Int(2),
            Value::Ref(majit_ir::GcRef(0x1000)),
            Value::Ref(majit_ir::GcRef(0x2000)),
        ];

        // Sound mapping: LABEL slot i takes state value `sources[i]`. The
        // permutation is not the identity, so a pack that silently passed its
        // input through would fail this assert.
        let (meta, _token) = meta_with_front_label_int_ref_ref_ref(7, Some(vec![1, 2, 3, 2]));
        assert_eq!(
            meta.front_target_inputarg_types(7),
            Some(vec![Type::Int, Type::Ref, Type::Ref, Type::Ref])
        );
        let packed = meta
            .pack_front_target_live_values(7, &state_order)
            .expect("a complete, type-agreeing mapping packs");
        assert_eq!(
            packed,
            vec![
                Value::Int(2),
                Value::Ref(majit_ir::GcRef(0x1000)),
                Value::Ref(majit_ir::GcRef(0x2000)),
                Value::Ref(majit_ir::GcRef(0x1000)),
            ]
        );
        assert_ne!(packed, state_order, "the pack must not be a pass-through");

        // Incomplete mapping: three sources for a four-argument LABEL. This is
        // the `pi.jinseo` shape — the fourth LABEL argument is a trace-internal
        // value with no state field behind it, so there is nothing to enter with.
        let (meta, _token) = meta_with_front_label_int_ref_ref_ref(8, Some(vec![1, 2, 3]));
        assert_eq!(meta.pack_front_target_live_values(8, &state_order), None);

        // Right arity, wrong types: the identity mapping puts `Int(2)` in the
        // LABEL's second slot, which is `Ref`.
        let (meta, _token) = meta_with_front_label_int_ref_ref_ref(9, Some(vec![0, 1, 2, 3]));
        assert_eq!(meta.pack_front_target_live_values(9, &state_order), None);

        // No mapping recorded at all.
        let (meta, _token) = meta_with_front_label_int_ref_ref_ref(10, None);
        assert_eq!(meta.pack_front_target_live_values(10, &state_order), None);
    }

    /// `pyjitpl.py:3319` reads the virtualizable out of a DECLARED red
    /// position; it never searches the reds for it. A red that happens to hold
    /// the same pointer earlier in the vector — another name for the same
    /// object — must not take the identity's place.
    #[test]
    fn test_declared_identity_position_wins_over_an_earlier_alias() {
        let vable = 0x4000usize;
        let mut info = VirtualizableInfo::without_vable_token();
        info.identity_ref_bank_index = Some(1);
        info.identity_live_index = Some(2);
        // reds: [alias (Ref), stackpos (Int), &state (Ref)].
        let live_values = [
            Value::Ref(majit_ir::GcRef(vable)),
            Value::Int(7),
            Value::Ref(majit_ir::GcRef(vable)),
        ];

        assert_eq!(
            MetaInterp::<()>::identity_live_position(&info, &live_values, vable as *const u8),
            Some(2),
            "the declared position, not the first pointer match",
        );
    }

    /// Bridge entry rebuilds the reds from a deadframe instead of the state's
    /// `extract_live`, and a host with a fixed array alongside a virtualizable
    /// one declares no position at all. Both fall back to the pointer match.
    #[test]
    fn test_identity_position_falls_back_when_the_declaration_does_not_hold() {
        let vable = 0x4000usize;
        let live_values = [Value::Int(7), Value::Ref(majit_ir::GcRef(vable))];

        let mut declared_elsewhere = VirtualizableInfo::without_vable_token();
        declared_elsewhere.identity_ref_bank_index = Some(1);
        declared_elsewhere.identity_live_index = Some(5);
        assert_eq!(
            MetaInterp::<()>::identity_live_position(
                &declared_elsewhere,
                &live_values,
                vable as *const u8,
            ),
            Some(1),
            "a declaration the reds do not honour falls back to the pointer",
        );

        let mut undeclared = VirtualizableInfo::without_vable_token();
        undeclared.identity_ref_bank_index = Some(1);
        assert_eq!(
            MetaInterp::<()>::identity_live_position(&undeclared, &live_values, vable as *const u8),
            Some(1),
        );

        assert_eq!(
            MetaInterp::<()>::identity_live_position(
                &undeclared,
                &live_values,
                std::ptr::null::<u8>(),
            ),
            None,
            "no live pointer means no red holds the identity",
        );
    }

