    #[test]
    fn compiled_virtualizable_trace_does_not_use_raw_heap_ops() {
        let mut meta = MetaInterp::<()>::new(10);
        meta.finish_setup_descrs_for_jitdrivers();
        let info = test_vable_info_with_array();
        let fd24 = info.array_pointer_field_descr(0);
        let adesc = info.array_item_descr(0);
        // live_values[0] is the vable identity — must be Ref-typed per
        // virtualstate.py NotVirtualStateInfoPtr contract. A bare
        // Value::Int here makes `enum_forced_boxes_for_entry` reject the
        // label via the Box.type strict check.
        let _vable = start_tracing_with_virtualizable(
            &mut meta,
            info,
            &[
                Value::Ref(majit_ir::GcRef(0x1234)),
                Value::Int(10),
                Value::Int(20),
            ],
            vec![2],
        );

        let index = {
            let ctx = meta.trace_ctx().unwrap();
            ctx.const_int(1)
        };
        let (item, _) =
            meta.opimpl_getarrayitem_vable_int(0, OpRef::input_arg_ref(0), index, 1, fd24, adesc);
        if let Some(ctx) = meta.trace_ctx() {
            let g = ctx.record_guard(OpCode::GuardTrue, &[item], 0);
            // This trace HAS a virtualizable, so its guard snapshot must carry
            // the vable section — `pyjitpl.py capture_resumedata`
            // passes `self.virtualizable_boxes` whenever `vinfo is not None`.
            // The plain `capture_snapshot_for_last_guard` hardcodes an empty
            // vable array, which encodes a 0-length section and trips the
            // `resume.py:236-239` length check now armed in
            // `store_final_boxes_in_guard`.
            let (vable_boxes, vref_boxes) = ctx.build_snapshot_vable_vref_boxes();
            ctx.capture_snapshot_for_last_guard_with_vable_vref(
                &[
                    OpRef::input_arg_ref(0),
                    OpRef::input_arg_int(1),
                    OpRef::input_arg_int(2),
                ],
                0,
                0,
                0,
                &vable_boxes,
                &vref_boxes,
            );
            ctx.set_fail_args(
                g,
                &[
                    OpRef::input_arg_ref(0),
                    OpRef::input_arg_int(1),
                    OpRef::input_arg_int(2),
                ],
            );
        }
        meta.compile_loop(
            &[
                OpRef::input_arg_ref(0),
                OpRef::input_arg_int(1),
                OpRef::input_arg_int(2),
            ],
            (),
        );

        let compiled = meta.compiled_entry(777).expect("compiled entry");
        let trace = compiled
            .traces
            .get(&compiled.root_trace_id)
            .expect("root compiled trace");

        assert!(
            trace.ops.iter().all(|op| {
                !matches!(
                    op.opcode,
                    OpCode::GetfieldRawI
                        | OpCode::GetfieldRawR
                        | OpCode::GetfieldRawF
                        | OpCode::SetfieldRaw
                        | OpCode::GetarrayitemRawI
                        | OpCode::GetarrayitemRawR
                        | OpCode::GetarrayitemRawF
                        | OpCode::SetarrayitemRaw
                )
            }),
            "standard virtualizable loop should use vable boxes, not raw heap ops: {}",
            majit_ir::format_trace(&trace.ops, &trace.constants)
        );
        assert_eq!(item, OpRef::input_arg_int(2));
    }

    #[test]
